// Real illustrated body-shape icons (client-provided asset:
// Body_Shapes_List.svg), replacing the emoji (⏳🍐🍎📏🔺) previously
// used on the Body Type screen. Each is the colored square + line
// illustration cropped straight out of the original file — the
// title/description text baked into that file was cropped away since
// the screen already renders its own real text for those.
import React from 'react';
import { SvgXml } from 'react-native-svg';

export type BodyShapeKey = 'hourglass' | 'pear' | 'apple' | 'rectangle' | 'inverted_triangle';

